import OpenAI from 'openai';
import type { NostrEvent } from '@nostrify/nostrify';
import type { AISettings } from '@/contexts/AppContext';

/**
 * The in-chat assistant. A user can address the AI by starting a message with
 * `@ai`. The reply is generated by an OpenAI-compatible API (configured under
 * Settings) and then published by the user themselves as an ordinary NIP-C7
 * kind 9 chat message — but tagged as AI-generated (NIP-32, see below) so that
 * clients can render it as if it came from a distinct "AI" participant rather
 * than from the user's own profile.
 */

/** Trigger prefix. A message addressed to the AI starts with this (case-insensitive). */
const AI_TRIGGER = /^@ai\b[ \t]*/i;

/** Whether a composed message is addressed to the AI assistant. */
export function isAiPrompt(content: string): boolean {
  return AI_TRIGGER.test(content.trimStart());
}

/** Strip the leading `@ai` trigger, returning the actual prompt text. */
export function stripAiTrigger(content: string): string {
  return content.trimStart().replace(AI_TRIGGER, '').trim();
}

/**
 * NIP-32 label marking content as AI-generated.
 *
 * We follow the convention used by other Nostr clients (e.g. Clawstr): a
 * namespace declaration `["L", "agent"]` plus a label `["l", "ai", "agent"]`.
 * Any event carrying both is treated as AI-authored regardless of the signer's
 * own profile.
 */
export const AI_LABEL = {
  namespace: 'agent',
  value: 'ai',
} as const;

/** Tags to attach to a kind 9 message that was produced by the AI assistant. */
export function aiLabelTags(): string[][] {
  return [
    ['L', AI_LABEL.namespace],
    ['l', AI_LABEL.value, AI_LABEL.namespace],
  ];
}

/** Whether a Nostr event is AI-generated content (NIP-32 agent/ai label). */
export function isAiContent(event: NostrEvent): boolean {
  const hasNamespace = event.tags.some(
    ([name, value]) => name === 'L' && value === AI_LABEL.namespace,
  );
  const hasLabel = event.tags.some(
    ([name, value, ns]) =>
      name === 'l' && value === AI_LABEL.value && ns === AI_LABEL.namespace,
  );
  return hasNamespace && hasLabel;
}

/** Whether the AI provider is configured well enough to make a request. */
export function isAiConfigured(settings: AISettings): boolean {
  return Boolean(settings.baseURL.trim() && settings.model.trim());
}

/**
 * Create an OpenAI client for the configured provider. The request is made
 * directly from the browser, so `dangerouslyAllowBrowser` is required and the
 * API key is exposed locally — this is acceptable because the key is the user's
 * own and never leaves their device except to the provider they configured.
 */
export function createAIClient(settings: AISettings): OpenAI {
  return new OpenAI({
    baseURL: settings.baseURL.trim(),
    apiKey: settings.apiKey.trim() || 'no-key',
    dangerouslyAllowBrowser: true,
    fetch: async (input, init) => {
      let request = new Request(input, init);

      // App-attribution headers for OpenRouter.
      // https://openrouter.ai/docs/app-attribution
      if (settings.baseURL.includes('openrouter.ai')) {
        const headers = new Headers(request.headers);
        headers.set('HTTP-Referer', 'https://nostrhub.io');
        headers.set('X-Title', 'NostrHub');
        request = new Request(request, { headers });
      }

      return fetch(request);
    },
  });
}
